sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float highlights;
uniform float shadows;
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001) return half4(0.0);
    half3 col = c.rgb / c.a;
    half l = saturate(dot(col, half3(0.2126, 0.7152, 0.0722)));
    half hi = 1.89 * pow(l, 3.5) * (1.0 - l);
    half lo = 1.89 * pow(1.0 - l, 3.5) * l;
    half3 outc = clamp(col + (highlights - 1.0) * hi + (shadows - 1.0) * lo, 0.0, 1.0);
    return half4(outc * c.a, c.a);
}
